@staff_member_required
def inspect_kyc_dossier(request, dossier_id):
    if not request.user.has_perm('compliance.can_inspect_kyc'):
        raise PermissionDenied("Insufficient compliance clearances.")
    dossier = get_object_or_404(KycDossier, id=dossier_id, assigned_auditor=request.user)
    return render(request, 'admin/kyc_detail.html', {'dossier': dossier})
